  "Install to trial": "설치→체험",
  "Trial starts ÷ installs. Prefilled from RevenueCat or Superwall trials (else Mixpanel or attribution) over the same installs.": "체험 시작 수 ÷ 설치 수. RevenueCat 또는 Superwall 체험(없으면 Mixpanel 또는 기여 데이터)을 같은 설치 수로 나눠 미리 채워요.",
  "Trial to paid": "체험→유료",
  "Trials that convert to paid. Prefilled from RevenueCat's trial conversion rate, else paid ÷ trials from one source.": "유료로 전환되는 체험 비율. RevenueCat 체험 전환율, 없으면 같은 소스의 유료 ÷ 체험으로 미리 채워요.",
  "Monthly churn": "월 이탈률",
  "Share of monthly subscribers lost each month (weekly and quarterly plans follow it too). Prefilled from RevenueCat's churn chart.": "매달 잃는 월간 구독자 비율(주간·분기 요금제도 이를 따라요). RevenueCat 이탈 차트로 미리 채워요.",
  "Annual renewal": "연 갱신율",
  "Share of annual subscribers who renew after a year. RevenueCat needs a year of history to show it, so it starts at a typical 35%.": "1년 후 갱신하는 연간 구독자 비율. RevenueCat에서 보려면 1년의 기록이 필요하므로 일반적인 35%로 시작해요.",
  "Refund rate": "환불률",
  "Share of revenue refunded. Prefilled from RevenueCat's refund rate, else Superwall's refunds ÷ revenue.": "환불된 매출 비율. RevenueCat 환불률, 없으면 Superwall 환불 ÷ 매출로 미리 채워요.",
  "Store fee": "스토어 수수료",
  "The store's cut of each charge: 15% in the App Store Small Business Program and Google Play's first $1M (and for subscriptions after a year), 30% otherwise.": "결제마다 스토어가 가져가는 몫: App Store 스몰 비즈니스 프로그램과 Google Play 첫 100만 달러(1년이 지난 구독 포함)는 15%, 그 외에는 30%.",
  "Plans and price mix": "요금제와 가격 구성",
  "Gross price and share of new paying customers for each plan. Prefilled from RevenueCat's proceeds and new paid subscriptions by product duration, grossed back up by the store fee (an estimate: proceeds also hold renewals).": "요금제별 총가격과 신규 유료 고객 비중. RevenueCat의 상품 기간별 수익금과 신규 유료 구독에서 스토어 수수료를 되돌려 미리 채워요(추정치: 수익금에는 갱신도 포함돼요).",
  "Plan": "요금제",
  "Price": "가격",
  "Share of new payers": "신규 결제자 비중",
  "Remove plan": "요금제 삭제",
  "Add a plan": "요금제 추가",
  "Next 12 months": "향후 12개월",
  "Steady spend, new payers each month, renewals stacking up. The band: conversion 20% worse or better, churn 25% higher or 20% lower.": "광고비는 일정, 매달 신규 결제자, 갱신이 쌓여요. 범위: 전환율 20% 낮거나 높을 때, 이탈률 25% 높거나 20% 낮을 때.",
  "Subscribers": "구독자",
  "Paying subscribers at the end of month 12: every month's new payers, less those who churned or didn't renew (lifetime buyers count as kept).": "12개월 차 말의 유료 구독자: 매달의 신규 결제자에서 이탈하거나 갱신하지 않은 사람을 뺀 수(평생 구매자는 유지로 계산).",
  "Revenue (12 mo)": "매출 (12개월)",
  "Net revenue over the 12 months: every charge after the store's fee and refunds.": "12개월 순매출: 스토어 수수료와 환불을 뺀 모든 결제.",
  "Profit (12 mo)": "이익 (12개월)",
  "Net revenue − ad spend, summed over the 12 months. Other costs aren't counted.": "순매출 − 광고비의 12개월 합계. 기타 비용은 포함하지 않아요.",
  "When one month's new payers have earned back that month's ad spend (CAC = CPI ÷ (install to trial × trial to paid)).": "한 달의 신규 결제자가 그 달 광고비를 회수하는 시점(CAC = CPI ÷ (설치→체험 × 체험→유료)).",
  "Break-even": "손익분기",
  "Not within 12 months": "12개월 내 도달하지 않음",
  "The first month in which cumulative profit is back to zero or above.": "누적 이익이 처음으로 0 이상이 되는 달.",
  "Cumulative profit": "누적 이익",
  "Cumulative revenue": "누적 매출",
  "Likely range": "예상 범위",
