  "Profit": "이익",
  "Revenue over time": "매출 추이",
  "From RevenueCat": "RevenueCat 기준",
  "Connected. Press Sync now to load the last 90 days.": "연결되었어요. 지금 동기화를 눌러 최근 90일을 불러오세요.",
  "Gross revenue per day (RevenueCat's revenue chart), net of refunds recorded that day.": "일별 총매출(RevenueCat 매출 차트), 그날 기록된 환불 차감.",
  "MRR": "MRR",
  "Monthly recurring revenue each day: active subscriptions normalised to a month (RevenueCat's MRR chart).": "일별 월간 반복 매출: 활성 구독을 한 달 기준으로 환산(RevenueCat MRR 차트).",
  "New trials": "신규 체험",
  "Trials started each day (RevenueCat's new trials chart).": "매일 시작된 체험(RevenueCat 신규 체험 차트).",
  "New paid": "신규 유료",
  "New paying subscriptions each day, trial conversions included (RevenueCat's new paid subscriptions).": "매일의 신규 유료 구독, 체험 전환 포함(RevenueCat 신규 유료 구독).",
  "Churn": "이탈",
  "Subscriptions that churned each day (RevenueCat's churn chart).": "매일 이탈한 구독(RevenueCat 이탈 차트).",
  "Refunds": "환불",
  "Refunded revenue each day, by refund date (RevenueCat's refunds chart).": "환불일 기준 일별 환불액(RevenueCat 환불 차트).",
  "From RevenueCat · last {n} days · USD": "RevenueCat 기준 · 최근 {n}일 · 미국 달러",
  "RevenueCat metric": "RevenueCat 지표",
  "RevenueCat hasn't sent this chart yet. Sync again, or check the key's Charts & metrics access.": "RevenueCat에서 아직 이 차트를 보내지 않았어요. 다시 동기화하거나 키의 Charts & metrics 권한을 확인하세요.",
  "Nothing in this period yet.": "이 기간에는 아직 데이터가 없어요.",
  "MRR now": "현재 MRR",
  "Paywalls": "페이월",
  "From Superwall": "Superwall 기준",
  "Paywall views, purchases and conversion for every paywall and placement appear here.": "모든 페이월과 노출 위치의 조회수, 구매, 전환이 여기에 표시돼요.",
  "From Superwall{app} · production only · last {n} days": "Superwall{app} 기준 · 프로덕션만 · 최근 {n}일",
  "Paywall views": "페이월 조회수",
  "Times a paywall opened (Superwall's paywall_open event), sandbox left out.": "페이월이 열린 횟수(Superwall의 paywall_open 이벤트), 샌드박스 제외.",
  "Conversion": "전환율",
  "Trials started": "시작된 체험",
  "{amount} refunded": "{amount} 환불",
  "Revenue Superwall tracked per day (its revenue table, refunds as negative amounts), without RevenueCat's copy of Stripe sales.": "Superwall이 일별로 추적한 매출(매출 테이블, 환불은 음수), RevenueCat에 중복된 Stripe 매출 제외.",
  "Paywall views per day": "일별 페이월 조회수",
  "Hover a day for its purchases and conversion": "날짜에 마우스를 올리면 구매와 전환을 볼 수 있어요",
  "views": "조회",
  "Conversion by paywall": "페이월별 전환",
  "Conversion by placement": "노출 위치별 전환",
  "Bar: paywall views. Right: purchases and conversion.": "막대: 페이월 조회수. 오른쪽: 구매와 전환.",
  "Group by": "그룹 기준",
