  "Funnel and retention": "퍼널과 리텐션",
  "From Mixpanel": "Mixpanel 기준",
  "Your own funnel from install to purchase, the retention curve and active users appear here, from the events you map.": "매핑한 이벤트로 설치부터 구매까지의 퍼널, 리텐션 곡선, 활성 사용자가 여기에 표시돼요.",
  "From Mixpanel · unique users per day, summed over the last {n} days": "Mixpanel 기준 · 일별 순 사용자, 최근 {n}일 합계",
  "No one did {events} in the synced period. Check those event names on the Mixpanel connection card.": "동기화 기간에 {events}을(를) 한 사람이 없어요. Mixpanel 연결 카드에서 이벤트 이름을 확인하세요.",
  "Funnel": "퍼널",
  "Each step is the unique users who did its mapped event, per day, summed over the period. The steps are counted separately (not one user's path), so a step can exceed the one before it. Conversion is each step ÷ the first.": "각 단계는 매핑한 이벤트를 한 일별 순 사용자를 기간 동안 합한 값이에요. 단계는 따로 집계하므로(한 사용자의 경로가 아님) 앞 단계보다 클 수 있어요. 전환율은 각 단계 ÷ 첫 단계예요.",
  "Install to purchase, from your mapped events": "매핑한 이벤트 기준, 설치부터 구매까지",
  "Mean time from install to purchase: {days} (saved funnel, {n} converters).": "설치부터 구매까지 평균 시간: {days} (저장 퍼널, 전환자 {n}명).",
  "Retention": "리텐션",
  "Of the people who installed on a day, the share who did the active event again N days later, over every install cohort synced (weighted by cohort size). Day 0 is the install day.": "어느 날 설치한 사람 중 N일 후 다시 활성 이벤트를 한 비율이에요. 동기화된 모든 설치 코호트를 대상으로 하며(코호트 크기로 가중), 0일 차는 설치일이에요.",
  "Day 1 {d1} · Day 7 {d7} · Day 30 {d30}": "1일 차 {d1} · 7일 차 {d7} · 30일 차 {d30}",
  "{n} cohorts": "코호트 {n}개",
  "Retention appears once install cohorts are a few days old.": "설치 코호트가 며칠 지나면 리텐션이 표시돼요.",
  "Active users per day": "일별 활성 사용자",
  "Average {n} a day · unique users who did \"{event}\"": "하루 평균 {n}명 · \"{event}\"을(를) 한 순 사용자",
  "Saving…": "저장 중…",
  "Checking the connection…": "연결을 확인하는 중…",
