  "An analysis collects accounts' recent posts and reads what works in them: formats, hooks and what the audience asks for.": "분석은 계정의 최근 게시물을 모아 효과적인 요소(포맷, 훅, 시청자가 원하는 것)를 읽어 내요.",
  "An analysis is running": "분석이 진행 중이에요",
  "Analyses of social posts sit under each app's Research.": "소셜 게시물 분석은 각 앱의 리서치에 있어요.",
  "Analyses": "분석",
  "App settings": "앱 설정",
  "Appearance": "모양",
  "Ask the owner to add it in Settings.": "소유자에게 설정에서 추가해 달라고 요청하세요.",
  "Back to app": "앱으로 돌아가기",
  "Bring an ad you like, say what to change and add your own pictures: new versions come back in its exact style for {name}. Or describe a shot and make a video.": "마음에 드는 광고를 가져와 바꿀 점을 말하고 내 이미지를 더하면, 같은 스타일 그대로 {name}용 새 버전이 만들어져요. 장면을 설명해 동영상을 만들 수도 있어요.",
  "Check the list for {name}": "{name}의 목록 확인",
  "Close help": "도움말 닫기",
  "Close menu": "메뉴 닫기",
  "Connections": "연결",
  "Contact": "문의하기",
  "Cost per install: ad spend divided by installs.": "설치당 비용: 광고비를 설치 수로 나눈 값이에요.",
  "Couldn't load your apps. Reload the page to try again.": "앱을 불러오지 못했어요. 페이지를 새로고침해 다시 시도하세요.",
  "Created in your ad account but switched off: nothing spends until you turn it on in Ads Manager.": "광고 계정에 만들어졌지만 꺼져 있어요. 광고 관리자에서 켜기 전까지는 비용이 나가지 않아요.",
  "Creatives": "크리에이티브",
  "Customer acquisition cost: what you spent on ads for each new paying customer.": "고객 획득 비용: 새 유료 고객 한 명당 쓴 광고비예요.",
  "Dark": "다크",
  "Desktop runner": "데스크톱 러너",
  "Each app keeps its own research, creatives, ads and numbers.": "앱마다 리서치, 크리에이티브, 광고, 수치가 따로 관리돼요.",
  "Every analysis of social posts, for each app and the ones that name none. Each app's own are also under its Research › Social posts.": "앱별 분석과 앱이 지정되지 않은 분석을 포함한 모든 소셜 게시물 분석이에요. 각 앱의 분석은 그 앱의 리서치 › 소셜 게시물에도 있어요.",
  "Every app at once, with its numbers and next step.": "모든 앱의 수치와 다음 단계를 한눈에.",
  "Every app in this workspace: how each one is doing and what to do next.": "이 워크스페이스의 모든 앱: 각 앱의 현황과 다음에 할 일.",
  "Find my competitors": "내 경쟁사 찾기",
  "Free up space before it fills.": "가득 차기 전에 공간을 확보하세요.",
  "Free up space to keep saving ads and creatives.": "광고와 크리에이티브를 계속 저장하려면 공간을 확보하세요.",
  "General & plan": "일반 및 요금제",
  "Go to": "이동",
  "Guides for each key": "키별 가이드",
  "Help": "도움말",
  "Hide {name}'s pages": "{name} 페이지 숨기기",
  "How many months until a customer has paid back what it cost to win them.": "고객 획득 비용을 그 고객이 몇 개월 만에 회수해 주는지예요.",
  "How much of your storage is used, by app and by kind, and what to delete to free space.": "저장 공간을 앱별·종류별로 얼마나 쓰는지, 공간을 확보하려면 무엇을 삭제하면 되는지 보여 줘요.",
  "How the app is doing, and the one thing to do next.": "앱의 현황과 다음에 할 한 가지.",
  "It is set on the server for this workspace.": "이 워크스페이스는 서버에서 설정돼요.",
  "Keyboard shortcuts": "키보드 단축키",
  "Kind of analysis": "분석 유형",
  "Leave these empty unless you want this app's files in a folder of your own.": "이 앱의 파일을 내 폴더에 두려는 경우가 아니면 비워 두세요.",
  "Lifetime value divided by acquisition cost. Above 3 is healthy; below 1 loses money on every customer.": "LTV를 고객 획득 비용으로 나눈 값이에요. 3 이상이면 건강하고, 1 미만이면 고객마다 손해예요.",
  "Lifetime value: what one paying customer pays you over time.": "고객 생애 가치: 유료 고객 한 명이 오랫동안 지불하는 금액이에요.",
  "Light": "라이트",
  "Main": "기본",
  "Make your own ads from what works, in your brand.": "효과 있는 광고를 바탕으로 내 브랜드의 광고를 만들어요.",
  "Match the device": "기기 설정 따르기",
  "Match the device's theme": "기기 테마 따르기",
  "Members": "멤버",
  "Menu": "메뉴",
  "Menus, pages and messages. Your competitors' ads and your own copy stay in the language they were written in.": "메뉴, 페이지, 메시지의 언어예요. 경쟁사 광고와 내 카피는 작성된 언어 그대로 표시돼요.",
