  "Send approved ads to your Meta ad account, paused until you switch them on.": "승인한 광고를 Meta 광고 계정으로 보내요. 켜기 전까지는 일시 중지 상태예요.",
  "Settings": "설정",
  "Show {name}'s pages": "{name} 페이지 보기",
  "Social posts": "소셜 게시물",
  "Start a batch in New batch above, or remix an ad on the Remix tab: they're reviewed here.": "위의 새 배치에서 배치를 시작하거나 리믹스 탭에서 광고를 리믹스하세요. 결과는 여기에서 검토해요.",
  "Start with your competitors: the analysis finds them from your app's profile and reads what wins for them on each channel.": "경쟁사부터 시작하세요. 분석이 앱 프로필에서 경쟁사를 찾아 채널별로 무엇이 통하는지 읽어 내요.",
  "Step by step: where to find each key and ID, and what it costs. Add them under Settings › Your keys.": "각 키와 ID를 어디서 찾고 비용이 얼마인지 단계별로 안내해요. 설정 › 내 키에서 추가하세요.",
  "Storage is almost full": "저장 공간이 거의 찼어요",
  "Storage is full": "저장 공간이 가득 찼어요",
  "Storage {percent} full": "저장 공간 {percent} 사용",
  "Stuck, or something looks wrong? Write to us and say what you were doing.": "막히거나 이상한 점이 있나요? 무엇을 하고 있었는지 적어 문의해 주세요.",
  "Templates": "템플릿",
  "The accounts {name}'s pages work from: Meta for ads, and RevenueCat, Superwall, Mixpanel or AppStack for what customers earn.": "{name}의 페이지가 사용하는 계정: 광고는 Meta, 고객 매출은 RevenueCat, Superwall, Mixpanel 또는 AppStack.",
  "The ads, apps and posts that work for your competitors.": "경쟁사에게 효과 있는 광고, 앱, 게시물.",
  "The app's profile, brand and connected accounts.": "앱의 프로필, 브랜드, 연결된 계정.",
  "The language the app speaks to you.": "앱이 사용하는 언어예요.",
  "The last step stopped": "마지막 단계가 멈췄어요",
  "The part of a Meta campaign that holds the budget, audience and placements; its ads sit inside it.": "Meta 캠페인에서 예산, 타깃, 노출 위치를 담는 단위로, 광고가 그 안에 들어가요.",
  "The services this workspace uses. Each key is checked when you save it and kept in your own Supabase project.": "이 워크스페이스가 사용하는 서비스예요. 각 키는 저장할 때 확인되며 내 Supabase 프로젝트에 보관돼요.",
  "The steps to set up your app, one at a time.": "앱을 설정하는 단계를 하나씩.",
  "The steps to set up {name}, one at a time.": "{name}을(를) 설정하는 단계를 하나씩.",
  "Their ads": "경쟁사 광고",
  "This workspace's name, your plan and how much of it is used.": "이 워크스페이스의 이름, 요금제, 사용량.",
  "Turn a brief, a winning format or a competitor's ad into videos and image ads. Each one is checked against your brand's rules, and only the ones you approve can launch. {n} approved so far.": "브리프, 효과 있는 포맷, 경쟁사 광고를 동영상과 이미지 광고로 바꿔요. 각각 브랜드 규칙으로 검사하며, 승인한 것만 게재할 수 있어요. 지금까지 {n}개 승인.",
  "Updates": "업데이트",
  "Use the dark theme": "다크 테마 사용",
  "Use the light theme": "라이트 테마 사용",
  "What each page does": "페이지별 기능",
  "What each page of {name} does": "{name}의 페이지별 기능",
  "What every creative for {name} follows, and the pictures it uses. The essentials are here; the rest is under More detail.": "{name}의 모든 크리에이티브가 따르는 규칙과 사용하는 이미지예요. 핵심은 여기에, 나머지는 '자세히'에 있어요.",
  "What works in competitors' and creators' own posts on Instagram, TikTok and YouTube: formats, hooks and what their audience asks for. Every run is kept.": "경쟁사와 크리에이터가 Instagram, TikTok, YouTube에 올린 게시물에서 효과 있는 것: 포맷, 훅, 시청자가 원하는 것. 모든 실행 결과가 보관돼요.",
  "What your ads cost next to what customers pay you.": "광고비와 고객이 지불하는 금액을 나란히 봐요.",
  "What {name} is and who it's for: your profile, and the AI's fuller read of your links.": "{name}이(가) 무엇이고 누구를 위한 것인지: 내 프로필과 링크에 대한 AI의 자세한 분석.",
  "Where files go": "파일 저장 위치",
  "Where {name}'s files go, and deleting the app.": "{name}의 파일 저장 위치와 앱 삭제.",
  "Working out the next step…": "다음 단계를 확인하는 중…",
