  "{n} other analysis isn't tied to this app.": "이 앱과 연결되지 않은 다른 분석이 {n}개 있어요.",
  "Approved creatives arrive in your own Meta ad account as {paused} ads, in a campaign and an {adSet}. Nothing spends until you switch them on in Ads Manager.": "승인한 크리에이티브는 캠페인과 {adSet} 안에 {paused} 광고로 내 Meta 광고 계정에 들어가요. 광고 관리자에서 켜기 전까지는 비용이 나가지 않아요.",
