  "payback": "회수 기간",
  "{n} template for this app. Open it, add your words and pictures, and it's made in this style.": "이 앱의 템플릿은 {n}개예요. 열어서 문구와 이미지를 넣으면 이 스타일로 만들어져요.",
  "{n} templates for this app. Open one, add your words and pictures, and it's made in that style.": "이 앱의 템플릿은 {n}개예요. 하나를 열어 문구와 이미지를 넣으면 그 스타일로 만들어져요.",
  "A Meta system user token and app secret, in Settings › Your keys": "Meta 시스템 사용자 토큰과 앱 시크릿 (설정 › 내 키)",
  "This app's Meta ad account and Facebook Page, in App settings › Connections": "이 앱의 Meta 광고 계정과 Facebook 페이지 (앱 설정 › 연결)",
  "Add both keys in Settings › Your keys. They are checked together once both are saved.": "설정 › 내 키에서 두 키를 모두 추가하세요. 둘 다 저장하면 함께 확인해요.",
  "App stores": "앱 스토어",
