  "Some characters aren't in the built-in font: {chars}. They show as empty boxes: replace them or upload a brand font that has them.": "내장 글꼴에 없는 글자가 있어요: {chars}. 빈 상자로 표시되니 다른 표현으로 바꾸거나 이 글자가 들어 있는 브랜드 글꼴을 업로드하세요.",
  // F3 Launch and Measure
  "Everything Launch creates is paused: nothing spends until you publish it in Ads Manager.": "게재에서 만드는 모든 항목은 일시 중지 상태예요. 광고 관리자에서 게시하기 전까지는 비용이 나가지 않아요.",
