  "The campaign “{name}” was created (paused). Pick it under “A new ad set in an existing campaign” to try again.": "‘{name}’ 캠페인이 만들어졌어요(일시 중지됨). ‘기존 캠페인에 새 광고 세트’에서 이 캠페인을 선택해 다시 시도하세요.",
  "Ad account {id}": "광고 계정 {id}",
