  "Each creative becomes its own ad, so Meta can find the winner. Videos use Meta's thumbnail (or the creative's cover).": "크리에이티브마다 광고가 하나씩 만들어져 Meta가 성과 좋은 광고를 찾을 수 있어요. 동영상에는 Meta 썸네일(또는 크리에이티브 커버)이 쓰여요.",
  "One ad with 2–10 cards people swipe through, each with its own headline and link. Good for showing several features.": "넘겨 보는 카드 2~10장으로 된 광고 1개로, 카드마다 헤드라인과 링크가 있어요. 여러 기능을 보여 주기에 좋아요.",
  "One ad, with the best-fitting version in each placement: for example a 4:5 for feeds and a 9:16 for Stories and Reels. Exactly one version is the fallback.": "광고 1개가 노출 위치마다 가장 잘 맞는 버전으로 보여요. 예를 들어 피드에는 4:5, 스토리와 릴스에는 9:16이에요. 대체 버전은 정확히 1개예요.",
  "Pick two or more creatives for a carousel or placement versions.": "슬라이드나 노출 위치별 버전을 만들려면 크리에이티브를 2개 이상 선택하세요.",
  "Use each creative’s own approved headline and text (the copy below fills any gaps)": "각 크리에이티브의 승인된 헤드라인과 문구 사용(빠진 부분은 아래 문구로 채워요)",
