  "Made with AI?": "AI로 만들었나요?",
  "Meta asks advertisers to say whether the media was made or edited with AI; it may then show an “AI info” label where the law asks for it (the EU, India, Taiwan, California, New York).": "Meta는 광고주에게 미디어를 AI로 만들거나 편집했는지 밝히도록 요청해요. 법으로 요구하는 지역(EU, 인도, 대만, 캘리포니아, 뉴욕)에서는 ‘AI 정보’ 라벨이 표시될 수 있어요.",
  "Yes, made or edited with AI": "예, AI로 만들거나 편집했어요",
