  "URL parameters": "URL 매개변수",
  "Advantage+ creative": "Advantage+ 크리에이티브",
  "Lets Meta touch up the media and rewrite text per person (brightness, animation, text variations). Off keeps each ad exactly as approved.": "Meta가 사람마다 미디어를 보정하고 문구를 바꿔 써요(밝기, 애니메이션, 문구 변형). 끄면 각 광고가 승인한 그대로 유지돼요.",
  "Optional tags added to the link.": "링크에 붙이는 선택 태그예요.",
