  "Only where you pick. Fewer places usually costs more per result.": "선택한 곳에만 표시돼요. 위치가 적을수록 결과당 비용이 보통 더 높아요.",
  "EU transparency (Digital Services Act)": "EU 투명성(디지털 서비스법)",
  "Ads shown in the EU name who benefits from them and who pays for them.": "EU에 표시되는 광고에는 수혜자와 비용 지불자를 밝혀야 해요.",
