  "Sync now": "지금 동기화",
  "Export": "내보내기",
  "Count paying customers from": "유료 고객 집계 기준",
  "AppStack and Meta each attribute customers to the ads (AppStack can over-count, Meta under-counts on iOS); RevenueCat counts every new payer, organic included (blended). Per-ad numbers always use AppStack, or Meta when AppStack isn't connected.": "AppStack과 Meta는 각각 고객을 광고에 기여시켜요(AppStack은 과다 집계될 수 있고, Meta는 iOS에서 적게 집계돼요). RevenueCat은 오가닉을 포함한 모든 신규 결제자를 집계해요(블렌디드). 광고별 수치는 항상 AppStack을 쓰고, AppStack이 연결되지 않았으면 Meta를 써요.",
  "Source of truth for CAC": "CAC 기준 데이터",
  "RevenueCat (blended)": "RevenueCat (블렌디드)",
  "Auto: AppStack when it's connected": "자동: 연결되어 있으면 AppStack",
  "Ads haven't started yet": "광고가 아직 시작되지 않았어요",
  "{source} didn't sync": "{source} 동기화 실패",
  "Meta is connected": "Meta가 연결되었어요",
  "The ad account has no delivery yet.": "광고 계정에 아직 게재 기록이 없어요.",
  "Once the first campaign spends, its spend, installs and cost per customer appear here, split into testing and scaling.": "첫 캠페인이 지출을 시작하면 지출, 설치, 고객당 비용이 테스트와 확장으로 나뉘어 여기에 표시돼요.",
  "Press Sync now to pull spend, installs and cost per customer from your ad account.": "'지금 동기화'를 누르면 광고 계정에서 지출, 설치, 고객당 비용을 가져와요.",
  "{n} impressions · CPM {cpm}": "노출 {n}회 · CPM {cpm}",
  "Installs ({source})": "설치 ({source})",
  "Trials ({source})": "체험 ({source})",
  "{amount} per trial": "체험당 {amount}",
  "ROAS (blended)": "ROAS (블렌디드)",
  "Attributed {roas} ({source})": "기여 {roas} ({source})",
  "Needs an exchange rate: sync again": "환율이 필요해요. 다시 동기화하세요",
  "Cost per paying customer": "유료 고객당 비용",
