  "vs previous {n} days": "이전 {n}일 대비",
  "No paying customers attributed in this period yet.": "이 기간에 기여된 유료 고객이 아직 없어요.",
  "Set an LTV (or connect RevenueCat) to see the margin per customer.": "LTV를 설정하거나 RevenueCat을 연결하면 고객당 마진을 볼 수 있어요.",
  "Spend isn't in USD yet, so it can't be set against LTV.": "지출이 아직 USD가 아니어서 LTV와 비교할 수 없어요.",
  "{amount} more than a customer is worth ({ltv} LTV). Every new customer loses money at this cost.": "고객 한 명의 가치(LTV {ltv})보다 {amount} 더 들어요. 이 비용이면 신규 고객마다 손해예요.",
  "{amount} kept per customer against {ltv} LTV.": "LTV {ltv} 기준으로 고객당 {amount}이 남아요.",
  "Attributed range": "기여 범위",
  "AppStack {appstack} · Meta {meta}. The two sources are never added: the true CAC most likely sits between them.": "AppStack {appstack} · Meta {meta}. 두 출처는 절대 합산하지 않아요. 실제 CAC는 그 사이일 가능성이 높아요.",
  "Blended CAC": "블렌디드 CAC",
  "Healthy": "양호",
