  "LTV basis": "LTV 기준",
  "LTV in USD": "LTV (USD)",
  "Spend needs converting to USD first: sync again to fetch the exchange rate.": "먼저 지출을 USD로 환산해야 해요. 다시 동기화해서 환율을 가져오세요.",
  "Needs an LTV: connect RevenueCat or set one in the cost card.": "LTV가 필요해요. RevenueCat을 연결하거나 비용 카드에서 설정하세요.",
  "Appears once the ads have brought a paying customer.": "광고로 유료 고객이 생기면 표시돼요.",
  "Campaigns without a role": "역할이 없는 캠페인",
  "Testing spend": "테스트 지출",
  "Scaling spend": "확장 지출",
  "What each customer leaves": "고객당 남는 금액",
  "Why each customer loses money": "고객마다 손해가 나는 이유",
  "{amount} kept per paying customer after ad spend": "광고비를 빼고 유료 고객당 {amount}이 남아요",
  "{amount} lost per paying customer after ad spend": "광고비를 빼면 유료 고객당 {amount} 손해예요",
  "All spend is still in testing: expect CAC to fall once winners move to scaling.": "지출이 아직 모두 테스트 단계예요. 성과 우수 광고가 확장으로 옮겨가면 CAC가 내려갈 거예요.",
  "Nothing urgent": "급한 일 없음",
  "No creative is above target CAC and nothing failed to sync.": "목표 CAC를 넘는 크리에이티브가 없고 동기화 실패도 없어요.",
  "spend": "지출",
  "each": "건당",
  "{source} solid, {other} dashed; hover a day for its spend": "{source}는 실선, {other}는 점선이에요. 날짜에 마우스를 올리면 그날 지출이 보여요",
  "Attributed by {source}; hover a day for its spend": "{source} 기여 기준이에요. 날짜에 마우스를 올리면 그날 지출이 보여요",
  "Attributed by {source}": "{source} 기여 기준",
  "Today solid; dashed line is today's daily budget": "오늘은 채운 막대, 점선은 오늘의 일일 예산이에요",
