  "Ads grouped by the format their creative was made from": "크리에이티브를 만든 포맷별로 광고를 묶었어요",
  "Ads grouped by the hook in Launch's ad name": "게재 광고 이름의 훅별로 광고를 묶었어요",
  "Testing and scaling campaigns apart; CAC against LTV on the gauge": "테스트와 확장 캠페인을 나눠서 보여 줘요. 게이지는 LTV 대비 CAC예요",
  "Level": "단위",
