  "CAC {cac} against {ltv} LTV": "CAC {cac} / LTV {ltv}",
  "Role of {name}": "{name}의 역할",
  "No role": "역할 없음",
  "No delivery in this period. Pick a longer range, or press Sync now.": "이 기간에는 게재가 없어요. 더 긴 기간을 고르거나 '지금 동기화'를 누르세요.",
  "Customers and CAC per row count {source}'s attribution; the small figure is {other}'s, never added. Meta reports iOS (SKAdNetwork / AEM) results 1–3 days late, so the last days run low.": "행별 고객과 CAC는 {source}의 기여 기준이에요. 작은 숫자는 {other}의 수치이며 합산하지 않아요. Meta는 iOS(SKAdNetwork / AEM) 결과를 1~3일 늦게 보고해서 최근 며칠은 낮게 나와요.",
  "Customers and CAC per row count {source}'s attribution. Meta reports iOS (SKAdNetwork / AEM) results 1–3 days late, so the last days run low.": "행별 고객과 CAC는 {source}의 기여 기준이에요. Meta는 iOS(SKAdNetwork / AEM) 결과를 1~3일 늦게 보고해서 최근 며칠은 낮게 나와요.",
  "Trials, new paid subscriptions, revenue and LTV appear here. Without it, set an LTV by hand in the cost card.": "체험, 신규 유료 구독, 매출, LTV가 여기에 표시돼요. 연결하지 않으면 비용 카드에서 LTV를 직접 설정하세요.",
  "Connected. Press Sync now to pull trials, revenue and LTV.": "연결되었어요. '지금 동기화'를 누르면 체험, 매출, LTV를 가져와요.",
  "From RevenueCat · last {n} days": "RevenueCat 기준 · 최근 {n}일",
  "Trial → paid": "체험 → 유료",
  "Trials started in the period that converted to paid ÷ those trials (RevenueCat's trial conversion rate). Recent trials are still pending, so this rises over time.": "기간 내 시작된 체험 중 유료로 전환된 수 ÷ 해당 체험 수(RevenueCat의 체험 전환율)예요. 최근 체험은 아직 결과가 나오지 않아 시간이 지나면 올라가요.",
  "New paid subscriptions": "신규 유료 구독",
  "New customers": "신규 고객",
  "Gross revenue in the period, net of refunds RevenueCat recorded in it.": "기간 내 총매출에서 RevenueCat이 그 기간에 기록한 환불을 뺀 금액이에요.",
  "Proceeds": "수익금",
  "Revenue after the store's commission and taxes: what reaches the bank. LTV uses this.": "스토어 수수료와 세금을 뺀 매출, 즉 실제로 입금되는 금액이에요. LTV는 이 값을 써요.",
  "Active now": "현재 활성",
