  "Right now, not for the period (RevenueCat's overview). MRR feeds the payback estimate.": "기간이 아니라 현재 기준이에요(RevenueCat 개요). MRR은 회수 기간 추정에 쓰여요.",
  "Annual vs monthly, by proceeds": "연간 vs 월간, 수익금 기준",
  "No paid subscriptions in this period yet.": "이 기간에는 아직 유료 구독이 없어요.",
  "No split by plan yet.": "아직 요금제별 구분이 없어요.",
  "How these numbers are calculated": "이 수치들의 계산 방법",
  "Spend from Meta, money from RevenueCat, attribution from AppStack and Meta": "지출은 Meta, 매출은 RevenueCat, 기여는 AppStack과 Meta에서 가져와요",
  "Currency": "통화",
  "The ad account bills in {currency}; spend is converted at 1 {currency} = {rate} USD (ECB rate of {date}).": "광고 계정은 {currency}로 청구돼요. 지출은 1 {currency} = {rate} USD로 환산해요({date} ECB 환율).",
  "The ad account bills in {currency}; spend is converted at 1 {currency} = {rate} USD (ECB rate).": "광고 계정은 {currency}로 청구돼요. 지출은 1 {currency} = {rate} USD로 환산해요(ECB 환율).",
  "The ad account bills in {currency} and no exchange rate is stored yet, so spend is shown in {currency} and nothing is set against RevenueCat's USD.": "광고 계정은 {currency}로 청구되고 아직 저장된 환율이 없어요. 그래서 지출은 {currency}로 표시하고 RevenueCat의 USD와 비교하지 않아요.",
