  "Your main product can't be deleted; edit it instead.": "기본 제품은 삭제할 수 없어요. 대신 수정해 주세요.",
  "Your pick sticks: the AI won't change it": "고른 종류는 유지돼요: AI가 바꾸지 않아요",
  "color-palette.json isn't valid JSON; colours skipped.": "color-palette.json이 올바른 JSON이 아니라서 색상을 건너뛰었어요.",
