  "Every prompt says “Say X, never Y”, and QA fails a creative or its copy that says Y (a former name works the same way: say your product’s name, never the old one). Required phrases must come with their word.": "모든 프롬프트에 \"X라고 하고, Y라고 하지 않기\"가 들어가고, 크리에이티브나 문구에 Y가 있으면 QA에서 불합격이에요(예전 이름도 같아요: 지금 제품명을 쓰고 예전 이름은 쓰지 않아요). 필수 문구는 해당 단어와 함께 써야 해요.",
