  "The desktop runner removes the background and saves a transparent PNG of this image (about {credits} Higgsfield credit). Composed ads can then place your real product instead of the model drawing it.": "데스크톱 러너가 배경을 지우고 이 이미지를 투명 배경 PNG로 저장해요(Higgsfield 크레딧 약 {credits}). 그러면 조판 광고에서 모델이 그리는 대신 실제 제품을 넣을 수 있어요.",
