  "A clean copy of the ad's layout with its brand, product, people and words taken out, saved to this product's Library.": "광고 레이아웃에서 브랜드, 제품, 인물, 문구를 뺀 깔끔한 사본이에요. 이 제품의 템플릿 라이브러리에 저장돼요.",
  "A product's library holds up to {n} of your own templates. Remove one first.": "제품 하나의 라이브러리에는 직접 만든 템플릿을 {n}개까지 둘 수 있어요. 먼저 하나를 삭제해 주세요.",
  "Billed by OpenAI in dollars, estimated from OpenAI's published prices (checked {date}).": "OpenAI가 달러로 청구해요. OpenAI 공개 가격({date} 확인) 기준 예상 금액이에요.",
  "Can't use that file": "이 파일은 사용할 수 없어요",
  "It hasn't been read yet.": "아직 읽지 않았어요.",
  "It leaves this product's Library. The original stays in {product}.": "이 제품의 라이브러리에서 빠져요. 원본은 {product}에 그대로 남아요.",
  "It leaves this product's Library. You can add it again from the starters any time.": "이 제품의 라이브러리에서 빠져요. 기본 템플릿에서 언제든 다시 추가할 수 있어요.",
  "No App Store reviews saved for this product yet. They're read with your App Store link.": "이 제품에 저장된 App Store 리뷰가 아직 없어요. 리뷰는 App Store 링크로 읽어 와요.",
  "Prices from Higgsfield's cost check on {date}; the live price is checked again before it runs.": "가격은 {date} Higgsfield 비용 확인 기준이에요. 실행 전에 실시간 가격을 한 번 더 확인해요.",
  "Reading the image didn't finish. Try again.": "이미지를 끝까지 읽지 못했어요. 다시 시도해 주세요.",
  "Stands in for the ad's product: your product.": "광고 속 제품 자리에 들어가요: 내 제품.",
  "Stands in for the ad's product: {slot}.": "광고 속 제품 자리에 들어가요: {slot}.",
  "Stats, reviews and ratings must be your own: real, sourced numbers (your user data or a published study) and a real customer's words, used with their permission. Made-up or rounded-up stats and invented reviews break Meta's ad policies and consumer-protection law.": "통계, 리뷰, 평점은 반드시 직접 확보한 것이어야 해요. 출처가 있는 실제 수치(자사 사용자 데이터나 공개된 연구)와, 실제 고객이 허락한 그 고객의 말만 쓸 수 있어요. 지어내거나 부풀린 통계, 가짜 리뷰는 Meta 광고 정책과 소비자 보호법을 위반해요.",
  "That file isn't a PNG, JPEG or WebP image.": "이 파일은 PNG, JPEG, WebP 이미지가 아니에요.",
  "That style isn't in the Style Library.": "스타일 라이브러리에 없는 스타일이에요.",
  "The prompt is {n} characters over Remix's limit; shorten the text.": "프롬프트가 리믹스 한도를 {n}자 넘었어요. 텍스트를 줄여 주세요.",
  "The request didn't go through. Check your connection and try again.": "요청이 전송되지 않았어요. 연결을 확인하고 다시 시도해 주세요.",
  "The server didn't answer. Try again.": "서버가 응답하지 않았어요. 다시 시도해 주세요.",
  "The template library isn't in the database yet (migrations {first} and {second}).": "템플릿 라이브러리가 아직 데이터베이스에 없어요(마이그레이션 {first}, {second}).",
  "The uploaded ad and its template are deleted from this product's storage (unless another product imported it). This can't be undone.": "업로드한 광고와 템플릿이 이 제품의 저장 공간에서 삭제돼요(다른 제품이 가져간 경우는 제외). 되돌릴 수 없어요.",
  "The video isn't loaded yet. Try again in a moment.": "동영상이 아직 로드되지 않았어요. 잠시 후 다시 시도해 주세요.",
  "This template can't be opened.": "이 템플릿을 열 수 없어요.",
