  "This workspace doesn't exist.": "존재하지 않는 워크스페이스예요.",
  "Upload an ad you like: it's read and turned into a clean, reusable template for this product. Or start from {n} proven formats. Templates stay with this product.": "마음에 드는 광고를 업로드하면 읽어서 이 제품에서 계속 쓸 수 있는 깔끔한 템플릿으로 만들어요. 검증된 포맷 {n}개로 시작할 수도 있어요. 템플릿은 이 제품에만 저장돼요.",
  "{name} isn't a PNG, JPEG or WebP image.": "{name}은(는) PNG, JPEG, WebP 이미지가 아니에요.",
