  "The prompt is {n} character over the limit; shorten the text.": "프롬프트가 한도를 {n}자 넘었어요. 문구를 줄여 주세요.",
  "The prompt is {n} characters over the limit; shorten the text.": "프롬프트가 한도를 {n}자 넘었어요. 문구를 줄여 주세요.",
  "The prompt {provider} gets": "{provider}에 전달되는 프롬프트",
