  "brand": "브랜드",
  "e.g. Put our bottle in her hand, change the review text to \"Finally a habit tracker that works\", keep everything else.": "예: 그녀 손에 우리 병을 들게 하고, 리뷰 문구를 \"드디어 제대로 되는 습관 트래커\"로 바꾸고, 나머지는 그대로 두기.",
