  "{n} characters on the image; over ~{max} may not fit the {aspect} safe area. Shorter reads better too.": "이미지 위 글자가 {n}자예요. 약 {max}자를 넘으면 {aspect} 안전 영역에 다 안 들어갈 수 있어요. 짧을수록 읽기도 좋아요.",
