  "Create {n} creative": "크리에이티브 {n}개 만들기",
  "Create {n} creatives": "크리에이티브 {n}개 만들기",
  "Starting…": "시작하는 중…",
  "Creatives can't be checked or approved until the AI is connected": "AI를 연결하기 전에는 크리에이티브를 검수하거나 승인할 수 없어요",
  "UGC videos wait in the queue until the desktop runner is set up and running.": "UGC 동영상은 데스크톱 러너가 설정되어 실행될 때까지 대기열에서 기다려요.",
  "AI videos wait in the queue until a Higgsfield key is added in Settings › Your keys.": "AI 동영상은 설정 › 내 키에서 Higgsfield 키를 추가할 때까지 대기열에서 기다려요.",
  "Images wait in the queue until a Higgsfield key is added in Settings › Your keys.": "이미지는 설정 › 내 키에서 Higgsfield 키를 추가할 때까지 대기열에서 기다려요.",
  "{kind} needs the desktop runner": "{kind}에는 데스크톱 러너가 필요해요",
  "static": "이미지 광고",
  "statics": "이미지 광고",
  "videos": "동영상",
  "The brief sums up what our top {kind} share.": "브리프에 성과가 가장 좋은 {kind}의 공통점을 정리했어요.",
  "The brief sums up what our top {kind} on {page} share.": "브리프에 {page}에서 성과가 가장 좋은 {kind}의 공통점을 정리했어요.",
  "The brief sums up what our top {n} {kind} share.": "브리프에 성과 상위 {n}개 {kind}의 공통점을 정리했어요.",
  "The brief sums up what our top {n} {kind} on {page} share.": "브리프에 {page}에서 성과 상위 {n}개 {kind}의 공통점을 정리했어요.",
  "{n} of their frames go along as style references.": "그중 {n}개 프레임이 스타일 참고로 함께 전달돼요.",
  "{n} of their images go along as style references.": "그중 {n}개 이미지가 스타일 참고로 함께 전달돼요.",
  "None of their images could be sent, so the brief carries the structure alone.": "이미지를 하나도 보낼 수 없어서 구성은 브리프로만 전달해요.",
  "Write a new hook: a clone of a live winner's line competes with it.": "새 훅을 써 주세요. 게재 중인 위너 광고의 문구를 그대로 쓰면 그 광고와 경쟁하게 돼요.",
  "More like our winners": "위너 광고와 비슷하게",
  "Their offer wording:": "오퍼 문구:",
  "{n} key frame of their video goes to Higgsfield as the shot and framing reference, then the images you picked and your screenshots.": "상대 동영상의 키 프레임 {n}개를 샷·구도 참고로 Higgsfield에 보내고, 이어서 고른 이미지와 스크린샷을 보내요.",
  "{n} key frames of their video go to Higgsfield as the shot and framing reference, then the images you picked and your screenshots.": "상대 동영상의 키 프레임 {n}개를 샷·구도 참고로 Higgsfield에 보내고, 이어서 고른 이미지와 스크린샷을 보내요.",
  "{n} key frame of their video goes to Higgsfield as the shot and framing reference, then your screenshots.": "상대 동영상의 키 프레임 {n}개를 샷·구도 참고로 Higgsfield에 보내고, 이어서 스크린샷을 보내요.",
  "{n} key frames of their video go to Higgsfield as the shot and framing reference, then your screenshots.": "상대 동영상의 키 프레임 {n}개를 샷·구도 참고로 Higgsfield에 보내고, 이어서 스크린샷을 보내요.",
  "Their image goes to Higgsfield as the layout and style reference, then the images you picked and your screenshots.": "상대 이미지를 레이아웃·스타일 참고로 Higgsfield에 보내고, 이어서 고른 이미지와 스크린샷을 보내요.",
  "Their image goes to Higgsfield as the layout and style reference, then your screenshots.": "상대 이미지를 레이아웃·스타일 참고로 Higgsfield에 보내고, 이어서 스크린샷을 보내요.",
  "Their media isn't used; the images you picked and your brand screenshots are the references.": "상대 미디어는 쓰지 않아요. 고른 이미지와 브랜드 스크린샷이 참고 자료예요.",
  "Their media isn't used; only your brand screenshots are references.": "상대 미디어는 쓰지 않아요. 브랜드 스크린샷만 참고해요.",
  "Our logo goes to Higgsfield right after their image, labelled as ours.": "우리 로고는 상대 이미지 바로 다음에 '우리 것'으로 표시해 Higgsfield에 보내요.",
  "Our logo ({label}) goes to Higgsfield right after their image, labelled as ours.": "우리 로고({label})는 상대 이미지 바로 다음에 '우리 것'으로 표시해 Higgsfield에 보내요.",
  "Our logo goes to Higgsfield right after their image, labelled as ours; the real file is then placed in the {where} of each finished image, inside Meta's safe area.": "우리 로고는 상대 이미지 바로 다음에 '우리 것'으로 표시해 Higgsfield에 보내요. 그다음 실제 파일을 완성된 각 이미지의 {where}, Meta 안전 영역 안에 배치해요.",
  "Our logo ({label}) goes to Higgsfield right after their image, labelled as ours; the real file is then placed in the {where} of each finished image, inside Meta's safe area.": "우리 로고({label})는 상대 이미지 바로 다음에 '우리 것'으로 표시해 Higgsfield에 보내요. 그다음 실제 파일을 완성된 각 이미지의 {where}, Meta 안전 영역 안에 배치해요.",
  "Recreating {page}'s ad": "{page}의 광고 재현",
  "The brief copies its style, structure and pattern for {app}.": "브리프는 그 스타일·구성·패턴을 {app}에 맞게 따라가요.",
  "Exact: the brief edits their ad and is sent as written, with nothing of the Studio's own added.": "정확히 재현: 브리프가 상대 광고를 수정하며, Studio 자체 내용은 추가하지 않고 그대로 보내요.",
  "Never in the creatives (checked in their on-screen text):": "크리에이티브에 절대 넣지 않을 것(화면 속 텍스트에서 검수):",
  "Its kind, placement, variants, lengths and references are filled in below and under More options. Picking another start clears them.": "종류, 노출 위치, 변형, 길이, 참고 이미지는 아래와 추가 옵션에 채워져 있어요. 다른 시작 방법을 고르면 지워져요.",
