  "max": "최대",
  "This Research brief already carries your brand: its look, voice, offers, words to avoid and forbidden claims. The Studio adds nothing of its own, and every one of those rules is checked.": "이 리서치 브리프에는 이미 브랜드의 룩, 톤, 오퍼, 피할 단어, 금지 표현이 담겨 있어요. Studio는 따로 추가하지 않고, 이 규칙을 모두 검수해요.",
