  "Start one in New batch above. Its jobs show here as they run.": "위의 새 배치에서 시작해 보세요. 실행 중인 작업이 여기에 표시돼요.",
  "Storage refused the upload. Open /setup and press Apply the update, then try again.": "저장소가 업로드를 거부했어요. /setup을 열어 업데이트 적용을 누른 뒤 다시 시도해 주세요.",
