  "The check reads the creative, not this copy: keep it to the same rules (no guarantees, no personal attributes).": "검수는 이 문구가 아니라 크리에이티브를 읽어요. 같은 규칙(효과 보장 금지, 개인 특성 언급 금지)을 지켜 주세요.",
  "The estimate changed to {price}; check it and confirm again.": "예상 비용이 {price}(으)로 바뀌었어요. 확인한 뒤 다시 승인해 주세요.",
  "The file or its words changed: it is checked again, then approval opens.": "파일이나 문구가 바뀌었어요. 다시 검수한 뒤 승인할 수 있어요.",
  "The finished file is still at the provider (links may expire):": "완성된 파일이 아직 제공업체에 있어요(링크가 만료될 수 있어요):",
  "The same prompt and images, on the same provider. A job that failed before it was charged costs the same again.": "같은 프롬프트와 이미지로 같은 제공업체에서 만들어요. 요금이 청구되기 전에 실패한 작업도 같은 비용이 들어요.",
  "The same prompt and images, the same model, on the other provider. It joins this batch as a new job; the failed one stays as it is.": "같은 프롬프트, 이미지, 모델로 다른 제공업체에서 만들어요. 새 작업으로 이 배치에 추가되고, 실패한 작업은 그대로 남아요.",
  "This video has no poster frame, which Launch needs. Make it again.": "이 동영상에는 게재에 필요한 썸네일 프레임이 없어요. 다시 만들어 주세요.",
