  "The posts were rendered, but the creatives backend didn't confirm them ({reason}), so they aren't checked yet. If they stay queued, start the batch again.": "게시물은 만들어졌지만 크리에이티브 백엔드가 확인하지 않아({reason}) 아직 검수되지 않았어요. 계속 대기 중이면 배치를 다시 시작해 주세요.",
