  "Who makes the images": "이미지를 만드는 곳",
  "OpenAI has no key yet: add one in Settings › Your keys.": "OpenAI 키가 아직 없어요. 설정 › 내 키에서 추가하세요.",
  "Billed by OpenAI in dollars, not Higgsfield credits (prices checked {date}).": "Higgsfield 크레딧이 아니라 OpenAI가 달러로 청구해요(가격 확인일: {date}).",
