  "The desktop runner isn't available on this account.": "이 계정에서는 데스크톱 러너를 사용할 수 없어요.",
  "Your plan allows {n} apps. Delete an app you no longer need to add another.": "내 요금제는 앱을 {n}개까지 쓸 수 있어요. 새로 추가하려면 필요 없는 앱을 삭제하세요.",
  "You have {n} generations waiting already. Let them finish (or cancel some), then try again.": "이미 대기 중인 생성이 {n}개 있어요. 끝날 때까지 기다리거나 일부를 취소한 뒤 다시 시도하세요.",
  "Your plan allows {n} generations a month, and this month's are used up.": "내 요금제는 한 달에 {n}번 생성할 수 있는데, 이번 달 분량을 모두 썼어요.",
