  "Google Drive folder ID": "Google Drive 폴더 ID",
  "The app's files couldn't be removed, so the app wasn't deleted. Try again in a moment.": "앱 파일을 삭제할 수 없어서 앱을 삭제하지 않았어요. 잠시 후 다시 시도해 주세요.",
  "Couldn't measure storage just now. Try again in a moment.": "지금은 저장 공간을 측정할 수 없었어요. 잠시 후 다시 시도해 주세요.",
  "Storage can't be measured yet: update the backend (Settings › Updates).": "아직 저장 공간을 측정할 수 없어요. 백엔드를 업데이트하세요(설정 › 업데이트).",
  "Storage can't be measured yet: your backend needs the latest update (Settings › Updates explains how).": "아직 저장 공간을 측정할 수 없어요. 백엔드를 최신 버전으로 업데이트해야 해요(방법은 설정 › 업데이트에 있어요).",
  "Couldn't measure storage just now.": "지금은 저장 공간을 측정할 수 없었어요.",

