  "Media to store": "저장할 미디어",
  "Meta and Google ads in any country, and TikTok ads shown in Europe, with your own keys. Billed per ad by Apify; you see the sources and the most it can cost before each collection.": "내 키로 모든 국가의 Meta·Google 광고와 유럽에 노출된 TikTok 광고를 수집해요. Apify가 광고당 요금을 청구하고, 수집할 때마다 소스와 최대 비용을 먼저 보여 드려요.",
  "Meta flagged this run. The extension started a 6-hour cooldown; don't collect again before 6 hours have passed.": "Meta가 이번 실행을 표시했어요. 확장 프로그램이 6시간 대기에 들어갔으니 6시간이 지나기 전에는 다시 수집하지 마세요.",
  "Meta flagged this run. The extension started a 6-hour cooldown; don't collect again before {time}.": "Meta가 이번 실행을 표시했어요. 확장 프로그램이 6시간 대기에 들어갔으니 {time} 전에는 다시 수집하지 마세요.",
  "Meta's Ad Library API": "Meta 광고 라이브러리 API",
  "Meta's impressions order compares ads within one advertiser: pick one to see their order.": "Meta 노출 순서는 한 광고주의 광고끼리만 비교해요. 광고주를 하나 선택하면 순서를 볼 수 있어요.",
