  "No creatives stored": "저장된 크리에이티브 없음",
  "No key needed for paid ads: collect a competitor's ads with the Ad Library extension and import the file on Research.": "유료 광고는 키가 필요 없어요. 광고 라이브러리 확장 프로그램으로 경쟁사 광고를 수집하고 리서치에서 파일을 가져오세요.",
  "No key needed for paid ads: collect a competitor's ads with the Ad Library extension and import the file on your app's Research page.": "유료 광고는 키가 필요 없어요. 광고 라이브러리 확장 프로그램으로 경쟁사 광고를 수집하고 앱의 리서치 페이지에서 파일을 가져오세요.",
