  "Nothing to import": "가져올 항목이 없어요",
  "Once the TypeSafe key is set, the AI reads each new ad for its format and hook, automatically, billed by TypeSafe.": "TypeSafe 키를 설정하면 AI가 새 광고마다 포맷과 훅을 자동으로 분석해요. 요금은 TypeSafe에서 청구해요.",
  "Once your OpenAI key is set, each new ad is read for its format and hook automatically:": "OpenAI 키를 설정하면 새 광고마다 포맷과 훅이 자동으로 분석돼요:",
  "One competitor list for the whole app: creative checks keep these names out of your ads, and each one's imported ads are filed under it.": "앱 전체에서 하나의 경쟁사 목록을 써요. 크리에이티브 검사가 이 이름이 내 광고에 들어가지 않게 막고, 가져온 광고는 각 경쟁사 아래에 정리돼요.",
  "One competitor list for the whole app: creative checks keep these names out of your ads, and followed ones are included when you collect automatically.": "앱 전체에서 하나의 경쟁사 목록을 써요. 크리에이티브 검사가 이 이름이 내 광고에 들어가지 않게 막고, 자동 수집할 때는 팔로우 중인 경쟁사가 포함돼요.",
  "One per creative": "크리에이티브당 1개",
  "Only the first {max} ads are imported, so no ads are marked as stopped.": "처음 {max}개 광고만 가져오므로 중지됨으로 표시되는 광고는 없어요.",
  "Open ad from {name}": "{name}의 광고 열기",
