  "Open or Search": "열기 또는 검색",
  "Open the brand's Facebook Page or its page in the Meta Ad Library and copy the link. Without one, its name is searched.": "브랜드의 Facebook 페이지나 Meta 광고 라이브러리 페이지를 열어 링크를 복사하세요. 링크가 없으면 이름으로 검색해요.",
  "Open your Facebook Page in the Ad Library, collect its ads with the Ad Library extension, then drop the file here and choose “Ours”.": "광고 라이브러리에서 내 Facebook 페이지를 열고 광고 라이브러리 확장 프로그램으로 광고를 수집한 뒤, 파일을 여기에 놓고 '우리 광고'를 선택하세요.",
  "Opens the Studio with a brief from what your top long-runners of a kind share (format, hook, proof, offer, CTA, layout), their images as style references and their offer wording. Every new ad still gets a new hook.": "같은 유형에서 오래 게재된 상위 광고들의 공통점(포맷, 훅, 근거, 오퍼, CTA, 레이아웃), 스타일 참고용 이미지, 오퍼 문구를 담은 브리프로 Studio를 열어요. 새 광고마다 훅은 새로 만들어요.",
  "Other advertisers": "기타 광고주",
  "Other {n}": "기타 {n}",
