  "Page": "페이지",
  "Pages": "페이지",
  "Paid ads your competitors are running now. The longer an ad runs and the more copies of it are live, the more likely it's working. Each new ad is read for its format, hook and structure on its own.": "경쟁사가 지금 게재 중인 유료 광고예요. 오래 게재되고 게재 중인 사본이 많을수록 효과가 있을 가능성이 높아요. 새 광고는 포맷, 훅, 구조가 자동으로 분석돼요.",
  "Partnership ad with {name}": "{name}과(와)의 파트너십 광고",
  "Partnership": "파트너십",
  "Pick a competitor above the ads to see theirs in Meta's impressions order.": "광고 위에서 경쟁사를 선택하면 해당 광고를 Meta 노출 순서로 볼 수 있어요.",
  "Picked in a competitor analysis": "경쟁사 분석에서 선택됨",
