  "Ranked #{rank} at {age}; an ad that age usually ranks about #{expected} ({curve}).": "게재 {age} 시점에 #{rank}위예요. 같은 기간의 광고는 보통 #{expected}위 정도예요({curve}).",
  "Read from the ad copy. Scanning it in Recreate hears the video, and it's read again from what's said.": "광고 문구로 분석했어요. 재현에서 스캔하면 동영상 음성을 듣고 말한 내용으로 다시 분석해요.",
  "Read from what's said in the video, with the ad copy.": "동영상에서 말한 내용과 광고 문구로 분석했어요.",
  "Read now": "지금 분석",
  "Reading needs {keys}": "분석하려면 {keys}이(가) 필요해요",
  "Reading {n} new ad: format, hook and what each line does. They fill in as they're read.": "새 광고 {n}개를 분석 중이에요: 포맷, 훅, 각 줄의 역할. 분석되는 대로 채워져요.",
  "Reading {n} new ads: format, hook and what each line does. They fill in as they're read.": "새 광고 {n}개를 분석 중이에요: 포맷, 훅, 각 줄의 역할. 분석되는 대로 채워져요.",
  "Running {days}": "{days} 게재 중",
