  "That isn't a file from the Ad Library extension. Drop the .json file it saved in Downloads/Ad Library, unchanged.": "광고 라이브러리 확장 프로그램의 파일이 아니에요. Downloads/Ad Library에 저장된 .json 파일을 수정하지 말고 그대로 놓으세요.",
  "That's not an ads file: choose the .json files the Ad Library extension saved.": "광고 파일이 아니에요. 광고 라이브러리 확장 프로그램이 저장한 .json 파일을 선택하세요.",
