  "The ads go up in parts of up to {n}: keep this tab open until the import finishes.": "광고는 최대 {n}개씩 나눠 올라가요. 가져오기가 끝날 때까지 이 탭을 열어 두세요.",
  "The advertiser name in TikTok's Ad Library": "TikTok 광고 라이브러리의 광고주 이름",
