  "The collectors couldn't be checked just now. Importing files works as usual; reload to check again.": "지금은 수집 도구를 확인하지 못했어요. 파일 가져오기는 그대로 돼요. 새로고침하면 다시 확인해요.",
  "The file has no ads. Check the Ad Library page and collect again.": "파일에 광고가 없어요. 광고 라이브러리 페이지를 확인하고 다시 수집하세요.",
  "The images and videos are deleted from storage. The ads stay in the list and fall back to their Ad Library links, which stop working after a few days. Collect the ads again and import the file to save them again.": "이미지와 동영상이 저장 공간에서 삭제돼요. 광고는 목록에 남고 광고 라이브러리 링크로 대체되지만, 그 링크는 며칠 뒤 작동하지 않아요. 다시 저장하려면 광고를 다시 수집해 파일을 가져오세요.",
  "The import stopped": "가져오기가 중단됐어요",
  "The order under Meta's \"total impressions\" sort when the ads were collected; ranks compare within one advertiser": "광고 수집 당시 Meta '총 노출수' 정렬 순서예요. 순위는 한 광고주 안에서만 비교해요",
  "Their ads, copy and posters still are. Freeing space doesn't change this per-file limit; it's your Supabase project's upload limit (Storage settings).": "광고, 문구, 포스터는 그대로 저장돼요. 공간을 비워도 이 파일당 한도는 바뀌지 않아요. Supabase 프로젝트의 업로드 한도예요(Storage 설정).",
  "Their images and videos are saved to storage in the background so they don't expire.": "이미지와 동영상은 만료되지 않도록 백그라운드에서 저장 공간에 저장돼요.",
  "Their images and videos couldn't be queued for storage: {error}": "이미지와 동영상을 저장 대기열에 넣지 못했어요: {error}",
