  "{n} videos ({size}) are over the {limit} upload limit and won't be stored.": "동영상 {n}개({size})가 업로드 한도 {limit}를 넘어 저장되지 않아요.",
  "{n}+ days": "{n}일 이상",
  "{pct}% long runners ({days}+ days)": "장기 게재 {pct}% ({days}일 이상)",
  "{sent} of {total}…": "{total}개 중 {sent}개…",
  "{used} of {quota} used ({pct}%) · {free} free": "{quota} 중 {used} 사용({pct}%) · 남은 공간 {free}",
  "(none on the Product page or the Brand page)": "(제품 페이지와 브랜드 페이지에 없음)",
  "A bright kitchen in the morning": "아침의 밝은 주방",
  "A clip made with Seedance 2.5 (on the Higgsfield API, or the desktop runner when the API isn't set up); no presenter avatar. It can follow their key frames.": "Seedance 2.5로 만드는 클립이에요(Higgsfield API, API가 설정되지 않았다면 데스크톱 러너). 출연자 아바타는 없고, 상대의 키프레임을 따라갈 수 있어요.",
  "A comparison of the app against the old way, with ticks and crosses. Never names a competitor.": "앱과 기존 방식을 체크와 엑스로 비교해요. 경쟁사 이름은 절대 언급하지 않아요.",
  "A credible presenter answers the question buyers keep asking, then points to the tool.": "신뢰감 있는 출연자가 구매자가 자주 묻는 질문에 답한 뒤 도구로 연결해요.",
  "A diary-style run through a day where the product shows up naturally at the moment it matters.": "일기처럼 하루를 따라가며 중요한 순간에 제품이 자연스럽게 등장해요.",
  "A different person": "다른 사람",
  "A first-person story told as it unfolds, turning into the lesson the product solves.": "1인칭으로 펼쳐지는 이야기가 제품이 해결하는 교훈으로 이어져요.",
  "A link of theirs would send your clicks to them.": "상대의 링크를 쓰면 우리 클릭이 상대에게 넘어가요.",
  "A man in his 20s, casual look": "20대 남성, 캐주얼한 차림",
  "A person talks to camera through most of it, so it's remade as an AI UGC video with a presenter.": "대부분 사람이 카메라를 보고 말하므로 출연자가 있는 AI UGC 동영상으로 다시 만들어요.",
  "A presenter in front of an app screen or a fact card, explaining it.": "출연자가 앱 화면이나 정보 카드 앞에서 설명해요.",
  "A presenter talking to camera, made with Marketing Studio on the desktop runner.": "카메라를 보고 말하는 출연자를 데스크톱 러너의 Marketing Studio로 만들어요.",
  "A presenter talks to camera in a casual style about the problem and the app as the fix (a presenter, never a customer).": "출연자가 편한 말투로 카메라를 보며 문제와 해결책인 앱을 이야기해요(출연자일 뿐, 고객이 아니에요).",
  "A real address that isn't yours.": "우리 것이 아닌 실제 주소예요.",
  "A real number that isn't yours.": "우리 것이 아닌 실제 번호예요.",
  "A real person's name or likeness; never reuse it.": "실존 인물의 이름이나 초상이에요. 절대 재사용하지 마세요.",
  "A real place that isn't yours.": "우리 것이 아닌 실제 장소예요.",
  "A real-feeling user talks to camera about the problem and how the product fixed it.": "실제 사용자 같은 사람이 카메라를 보며 문제와 제품이 어떻게 해결했는지 이야기해요.",
  "A short acted scene of a situation the buyer knows too well, with the product as the punchline.": "구매자에게 너무 익숙한 상황을 짧은 연기로 보여 주고 제품으로 마무리해요.",
  "A shot-by-shot prompt for a video tool (Higgsfield's Seedance, Sora, Veo). Generate here makes stills only; for a video, send it to Studio.": "동영상 도구(Higgsfield의 Seedance, Sora, Veo)용 샷별 프롬프트예요. '여기서 생성'은 정지 이미지만 만들어요. 동영상은 Studio로 보내세요.",
  "A still image in its style": "같은 스타일의 정지 이미지",
  "A video prompt": "동영상 프롬프트",
  "A way to make it yours:": "우리 것으로 바꾸는 방법:",
  "A woman in her 30s, casual, at her kitchen table": "30대 여성, 캐주얼한 차림, 주방 식탁에 앉아 있음",
  "AI / actor UGC": "AI/배우 UGC",
  "AI advice; you decide": "AI 조언일 뿐, 결정은 직접 하세요",
  "About {n} s": "약 {n}초",
  "Add an image key to generate here": "이미지 키를 추가하면 여기서 생성할 수 있어요",
  "Add images": "이미지 추가",
  "Add or sort images in App settings › Brand": "앱 설정 › 브랜드에서 이미지 추가·정렬",
  "Add product images in App settings › Brand": "앱 설정 › 브랜드에서 제품 이미지 추가",
  "Add your colours on the Brand page first.": "먼저 브랜드 페이지에서 우리 색상을 추가하세요.",
  "Address": "주소",
  "Adds it to Custom instructions, where you can edit or remove it": "맞춤 지시에 추가돼요. 거기서 수정하거나 삭제할 수 있어요",
  "An aspirational message over cinematic footage, tying the product to the life the buyer wants.": "영화 같은 영상 위에 동경을 자아내는 메시지를 얹어 제품을 구매자가 원하는 삶과 연결해요.",
  "An avatar, or describe one. A different person from theirs.": "아바타를 고르거나 직접 묘사하세요. 상대와 다른 사람이어야 해요.",
  "Angle": "앵글",
  "Ask the question the buyer is already asking themselves.": "구매자가 이미 스스로 묻고 있는 질문을 던져요.",
