  "Break down this video": "이 동영상 분석",
  "Break it down again": "다시 분석",
  "Built from the AI's read of their ad.": "AI가 상대 광고를 읽은 내용을 바탕으로 만들었어요.",
  "Built from the ad's own text and type (read the ad for a closer match).": "광고 자체의 텍스트와 유형으로 만들었어요(광고를 읽으면 더 비슷해져요).",
  "Call to action type": "CTA 유형",
  "Calm, precise, friendly": "차분하고, 정확하고, 친근하게",
  "Caption": "캡션",
