  "{name} says the account is out of credits or over its limit. Top it up on {name}'s site, then retry, or switch provider.": "{name}에 따르면 계정 크레딧이 부족하거나 한도를 넘었어요. {name} 사이트에서 충전한 뒤 다시 시도하거나 제공업체를 바꾸세요.",
