  "Meta blocked a run ({page}) in the last 6 hours. Cooldown until {time}.": "최근 6시간 안에 Meta가 실행({page})을 차단했어요. 쿨다운은 {time}까지예요.",
  "Meta blocked a run in the last 6 hours. Cooldown until {time}.": "최근 6시간 안에 Meta가 실행을 차단했어요. 쿨다운은 {time}까지예요.",
  "Meta doesn't share spend or conversions for these ads outside the EU; long runs, many variants and Meta's impressions order are the best signals of what's working.": "EU 밖에서는 Meta가 이 광고들의 지출이나 전환을 공개하지 않아요. 긴 게재 기간, 많은 변형, Meta의 노출 순위가 효과 있는 광고를 알려 주는 가장 좋은 신호예요.",
  "Meta shows 3 or more ads using this creative": "Meta에 이 크리에이티브를 쓰는 광고가 3개 이상 있어요",
