  "Of the ads first seen here {n}+ days ago, the share still running (\"–\": none seen that long ago yet)": "여기서 {n}일 이상 전에 처음 확인된 광고 중 아직 게재 중인 비율('–': 그만큼 오래전에 확인된 광고가 아직 없음)",
  "One or many .json files the Ad Library extension saved": "광고 라이브러리 확장 프로그램이 저장한 .json 파일(하나 또는 여러 개)",
