  "Our ads live {n}+ days: likely wearing out, so make the next version before they stop": "{n}일 이상 게재 중인 우리 광고. 피로도가 쌓였을 가능성이 높으니 멈추기 전에 다음 버전을 만드세요",
  "POV skit": "POV 콩트",
  "Paid-ads research isn't set up in the database yet (migration 20261002300000_paid_ads).": "유료 광고 리서치가 아직 데이터베이스에 설정되지 않았어요(migration 20261002300000_paid_ads).",
  "Parallel or back-to-back sessions from one connection are a common reason Meta blocks it for hours.": "같은 연결에서 동시에 또는 연달아 실행하면 Meta가 몇 시간 동안 차단하는 흔한 원인이 돼요.",
  "Partnership ads (run with a creator's or another Page) live 30+ days": "30일 이상 게재 중인 파트너십 광고(크리에이터나 다른 페이지와 함께 집행)",
  "Partnership ads": "파트너십 광고",
  "Paste the Page's link (facebook.com/…), its Ad Library link, or its numeric Page id.": "페이지 링크(facebook.com/…), 광고 라이브러리 링크 또는 숫자로 된 페이지 ID를 붙여 넣어 주세요.",
  "Paste the advertiser's name as TikTok's Ad Library shows it, or a library.tiktok.com link with its business id.": "TikTok 광고 라이브러리에 표시되는 광고주 이름이나 비즈니스 ID가 포함된 library.tiktok.com 링크를 붙여 넣어 주세요.",
  "Paste the competitor's website (like notion.so) or its advertiser link from adstransparency.google.com.": "경쟁사 웹사이트(예: notion.so)나 adstransparency.google.com의 광고주 링크를 붙여 넣어 주세요.",
  "Proven winners": "검증된 성과 우수 광고",
  "Ran 30+ days, then stopped: a former winner that wore out": "30일 이상 게재 후 중지. 한때 성과가 좋았다가 피로해진 광고예요",
  "Ran 30+ days, then stopped: what worked until it didn't, and angles they may come back to": "30일 이상 게재 후 중지. 효과가 떨어지기 전까지 통했던 광고이자, 경쟁사가 다시 쓸 수도 있는 앵글이에요",
