  "Share of live ads that are video": "게재 중인 광고 중 동영상의 비율",
  "Share still running, of the ads first seen here {n}+ days ago ({name} only): a higher share means advertisers keep paying for that kind of ad. Groups under 10 ads are left out. It sharpens with every import.": "여기서 {n}일 이상 전에 처음 확인된 광고 중 아직 게재 중인 비율({name}만). 비율이 높을수록 광고주가 그런 광고에 계속 돈을 쓴다는 뜻이에요. 광고가 10개 미만인 그룹은 제외해요. 가져올 때마다 더 정확해져요.",
  "Share still running, of the ads first seen here {n}+ days ago: a higher share means advertisers keep paying for that kind of ad. Groups under 10 ads are left out. It sharpens with every import.": "여기서 {n}일 이상 전에 처음 확인된 광고 중 아직 게재 중인 비율. 비율이 높을수록 광고주가 그런 광고에 계속 돈을 쓴다는 뜻이에요. 광고가 10개 미만인 그룹은 제외해요. 가져올 때마다 더 정확해져요.",
  "Show all the text": "전체 텍스트 보기",
