  "Switched off: {sources}. Turn them on in {link}.": "꺼짐: {sources}. {link}에서 켤 수 있어요.",
  "That Transparency Center link has no advertiser in it. Open the advertiser's page and copy its link (it has AR… in it).": "이 투명성 센터 링크에는 광고주가 없어요. 광고주 페이지를 열고 링크를 복사해 주세요(AR…가 들어 있어요).",
