  "The .json files the Ad Library extension saves: one per Page, as many as you like at once.": "광고 라이브러리 확장 프로그램이 저장하는 .json 파일이에요. 페이지마다 하나씩, 한 번에 여러 개를 넣을 수 있어요.",
  "The .json files the Ad Library extension saves: one per competitor, as many as you like at once.": "광고 라이브러리 확장 프로그램이 저장하는 .json 파일이에요. 경쟁사마다 하나씩, 한 번에 여러 개를 넣을 수 있어요.",
