  "The earlier versions couldn't be loaded.": "이전 버전을 불러오지 못했어요.",
  "The extension collects one competitor at a time, at least 30 minutes apart, and stops for 6 hours if Meta shows a block sign. It runs in its own small window: keep part of it visible while you work elsewhere.": "확장 프로그램은 경쟁사를 한 번에 하나씩, 30분 이상 간격을 두고 수집하며, Meta가 차단 신호를 보이면 6시간 동안 멈춰요. 별도의 작은 창에서 실행되니 다른 작업 중에도 창 일부가 보이게 두세요.",
  "The extension stopped and started a 6-hour cooldown. Visiting the Ad Library again from the same connection before it ends can stretch the block.": "확장 프로그램이 멈추고 6시간 쿨다운을 시작했어요. 끝나기 전에 같은 연결로 광고 라이브러리에 다시 접속하면 차단이 길어질 수 있어요.",
