  "None of the chosen accounts has a handle on the selected channels. Add handles with “Edit channels”.": "선택한 계정 중 선택한 채널에 핸들이 있는 계정이 없어요. '채널 편집'으로 핸들을 추가하세요.",
  "None of the chosen competitors has a handle on the selected channels. Add handles with “Edit channels”.": "선택한 경쟁사 중 선택한 채널에 핸들이 있는 곳이 없어요. '채널 편집'으로 핸들을 추가하세요.",
  "None of the chosen creators has a handle on the selected channels. Add handles with “Edit channels”.": "선택한 크리에이터 중 선택한 채널에 핸들이 있는 사람이 없어요. '채널 편집'으로 핸들을 추가하세요.",
