  "The AI names the brands you're up against with their social accounts, checks each one against your app, and you pick who to study.": "AI가 경쟁 브랜드와 소셜 계정을 찾아 하나씩 내 앱과 비교하고, 분석할 대상은 직접 고르면 돼요.",
  "The account": "계정",
  "The analysis, all its runs and their reports are deleted for good.": "이 분석과 모든 실행, 보고서가 영구적으로 삭제돼요.",
  "The app reads the brand's tagged posts and collab posts, then checks creators' bios for ties like “athlete @brand”, “ambassador” or a discount code. Posts from those creators count even when they don't tag the brand. Adds about $1.40.": "앱이 브랜드가 태그된 게시물과 협업 게시물을 읽고, 크리에이터 소개글에 'athlete @brand', 'ambassador', 할인 코드 같은 관계가 있는지 확인해요. 이런 크리에이터의 게시물은 브랜드를 태그하지 않아도 집계돼요. 약 $1.40가 추가돼요.",
  "The best came from {account}.": "최고 게시물은 {account}에서 나왔어요.",
