  "The list below is replaced by a fresh search. Competitors you added yourself are kept only if they're on your product profile.": "아래 목록이 새 검색 결과로 바뀌어요. 직접 추가한 경쟁사는 제품 프로필에 있을 때만 유지돼요.",
  "The pains they recognise": "공감하는 고민",
  "The server didn't answer. Check your connection and reload the page.": "서버가 응답하지 않아요. 연결을 확인하고 페이지를 새로고침하세요.",
  "The strongest format on {channel} is “{format}” (typical {views} views over {posts} posts).": "{channel}에서 가장 강한 포맷은 “{format}”이에요(게시물 {posts}개, 일반 조회수 {views}).",
  "The top hook on {channel}, from {account} · {views} views.": "{channel} 최고의 훅, {account} · 조회수 {views}.",
