  "Turn on “Read more comments” and run it again: up to 25 comments are read on each channel's most-viewed posts and sorted into what buyers want, ask and doubt.": "'댓글 더 읽기'를 켜고 다시 실행하세요. 채널별 조회수 상위 게시물의 댓글을 최대 25개 읽어 구매자가 원하는 것, 묻는 것, 의심하는 것으로 분류해요.",
  "Typical views": "일반 조회수",
