  "Up to 25 comments on each channel's 20 most-viewed posts, to find buyers and what your audience asks for. Adds about $1–4 per run.": "채널별 조회수 상위 20개 게시물에서 각각 댓글을 최대 25개 읽어 구매자와 시청자가 원하는 것을 찾아요. 실행당 약 $1–4가 추가돼요.",
  "Up to 25 comments on each channel's 20 most-viewed posts, to spot buyers and what the audience asks for.": "채널별 조회수 상위 20개 게시물에서 각각 댓글을 최대 25개 읽어 구매자와 시청자가 원하는 것을 찾아요.",
