  "Click {open} on a competitor above (it opens the Ad Library in a new tab), then click the extension's orange icon and {collect}.": "위에서 경쟁사의 '{open}'을(를) 클릭한 뒤(새 탭에서 광고 라이브러리가 열려요), 확장 프로그램의 주황색 아이콘에서 '{collect}'를 클릭하세요.",
  "Click {open} on one of your Pages above (it opens the Ad Library in a new tab), then click the extension's orange icon and {collect}.": "위에서 내 페이지 중 하나의 '{open}'을(를) 클릭한 뒤(새 탭에서 광고 라이브러리가 열려요), 확장 프로그램의 주황색 아이콘에서 '{collect}'를 클릭하세요.",
  "Add your Facebook Page above, then click {open} on it (it opens the Ad Library in a new tab), then click the extension's orange icon and {collect}.": "위에서 내 Facebook 페이지를 추가하고 '{open}'을(를) 클릭한 뒤(새 탭에서 광고 라이브러리가 열려요), 확장 프로그램의 주황색 아이콘에서 '{collect}'를 클릭하세요.",
  "Add a competitor above, then click {open} on it (it opens the Ad Library in a new tab), then click the extension's orange icon and {collect}.": "위에서 경쟁사를 추가하고 '{open}'을(를) 클릭한 뒤(새 탭에서 광고 라이브러리가 열려요), 확장 프로그램의 주황색 아이콘에서 '{collect}'를 클릭하세요.",
  "For their organic posts, see {link}.": "자연 게시물은 {link}에서 보세요.",
  "Install it once: {guide} shows each click, from unzipping to pinning it in Chrome.": "한 번만 설치하면 돼요. {guide}에서 압축 해제부터 Chrome에 고정하기까지 모든 클릭을 보여 줘요.",
  "the step-by-step guide": "단계별 가이드",
  "Pause following": "팔로우 일시 중지",
  "This can't be undone: to follow it again, add it and collect its ads again. To keep its data and only stop updating it, use Pause following instead.": "되돌릴 수 없어요. 다시 보려면 추가하고 광고를 다시 수집하세요. 데이터는 두고 업데이트만 멈추려면 대신 '팔로우 일시 중지'를 쓰세요.",
  "{free} the Chrome extension saves a competitor's Meta ads as a file you drop on this page (steps under “How to get ads in”).": "{free} Chrome 확장 프로그램이 경쟁사의 Meta 광고를 파일로 저장하면, 그 파일을 이 페이지에 놓으면 돼요(방법은 '광고 가져오는 방법'에 있어요).",
  "Want it quicker? {make} gives a ready-made prompt, one image here, or a Studio batch.": "더 빨리 만들고 싶나요? {make}에서 준비된 프롬프트, 여기서 이미지 한 장, 또는 Studio 일괄 제작을 쓸 수 있어요.",
  "Seedance follows their shots and framing ({level}, set by Closeness) while every brand detail becomes yours; their video file itself is never sent.": "Seedance가 상대의 샷과 구도를 따라가고({level}, 유사도에서 설정) 브랜드 요소는 모두 우리 것으로 바뀌어요. 상대의 동영상 파일 자체는 전송되지 않아요.",
  "Use {n} key frame of their video as Higgsfield's reference (at {times}).": "상대 동영상의 키프레임 {n}개({times} 시점)를 Higgsfield 참고 이미지로 사용해요.",
  "Use {n} key frames of their video as Higgsfield's reference (at {times}).": "상대 동영상의 키프레임 {n}개({times} 시점)를 Higgsfield 참고 이미지로 사용해요.",
  "No AI product profile yet: add your website or App Store link on the {link} so the prompt knows who you sell to, your promise and your proof.": "아직 AI 제품 프로필이 없어요. {link}에 웹사이트나 App Store 링크를 추가하면 프롬프트가 타깃 고객, 약속, 근거를 알 수 있어요.",
  "Profile tab of App settings": "앱 설정의 프로필 탭",
