  "The app hikers rate 4.7": "등산객이 4.7점을 준 앱",
  "Plan a weekend hike in a minute.": "주말 등산을 1분 만에 계획하세요.",
  "Says “in a tap”: make sure the app really plans a trail in one tap.": "‘한 번 탭으로’라고 써 있어요. 앱이 정말 한 번 탭으로 등산로를 계획하는지 확인하세요.",
  "Higgsfield stopped the job: its content policy refused the prompt. No credits were charged.": "Higgsfield가 작업을 멈췄어요. 콘텐츠 정책에서 프롬프트를 거부했어요. 크레딧은 차감되지 않았어요.",
  "Ad rejected: it mentions a price the landing page doesn't show.": "광고가 거부됐어요. 랜딩 페이지에 없는 가격을 언급하고 있어요.",
  "A hike planner for weekend hikers: trails near you, the weather at the top and maps that work offline.": "주말 등산객을 위한 등산 계획 앱이에요. 가까운 등산로, 정상 날씨, 오프라인에서도 되는 지도를 담았어요.",
  "Weekend hikers, 25 to 45": "주말 등산객, 25~45세",
