  "Plain, warm and outdoorsy. Short sentences.": "담백하고 따뜻하게, 아웃도어 느낌으로. 문장은 짧게.",
  "Plans the whole day (trail, weather and drive) in one screen, and works with no signal.": "하루 전체(등산로, 날씨, 이동)를 한 화면에서 계획하고, 신호가 없어도 쓸 수 있어요.",
