  "A presenter talking to camera, made with Marketing Studio. It isn't available on your plan yet.": "출연자가 카메라를 보고 말하는 영상으로, Marketing Studio로 만들어요. 아직 현재 요금제에서는 쓸 수 없어요.",
  "A clip made with Seedance 2.5 on the Higgsfield API; no presenter avatar. It can follow their key frames.": "Higgsfield API의 Seedance 2.5로 만드는 클립이고, 출연자 아바타는 없어요. 상대 광고의 키 프레임을 따라갈 수 있어요.",
  "Their ads, copy and posters still are. Freeing space doesn't change this per-file limit; it comes with your plan.": "상대의 광고, 문구, 포스터는 그대로 저장돼요. 공간을 비워도 파일당 한도는 바뀌지 않아요. 한도는 요금제에 따라 정해져요.",
  "Optional. Most people don't need this: add a Google Drive folder to share finished creatives there.": "선택 사항이에요. 대부분은 필요 없어요. Google Drive 폴더를 추가하면 완성된 크리에이티브를 그곳에 공유할 수 있어요.",
  "Optional. Most people never need these.": "선택 사항이에요. 대부분은 필요 없어요.",
