  "Back to the home page": "홈페이지로 돌아가기",
  "Type the confirmation word to delete your account.": "계정을 삭제하려면 확인 단어를 입력하세요.",
  "Couldn't reach the backend. Nothing more was deleted; try again in a moment.": "백엔드에 연결할 수 없었어요. 더 삭제된 것은 없어요. 잠시 후 다시 시도하세요.",
  "This workspace's backend is too old to delete accounts. Ask whoever runs it to apply the latest update.": "이 워크스페이스의 백엔드가 오래돼서 계정을 삭제할 수 없어요. 운영자에게 최신 업데이트를 적용해 달라고 요청하세요.",
  "The owner can't delete their account here. Give the workspace to someone else first, or delete the whole workspace (its Supabase project).": "소유자는 여기서 자신의 계정을 삭제할 수 없어요. 먼저 워크스페이스를 다른 사람에게 넘기거나, 워크스페이스 전체(해당 Supabase 프로젝트)를 삭제하세요.",
  "Accounts can't be deleted in this workspace. Ask whoever runs it.": "이 워크스페이스에서는 계정을 삭제할 수 없어요. 운영자에게 문의하세요.",
  "Your account wasn't fully deleted yet. Try again: it carries on where it stopped.": "계정이 아직 완전히 삭제되지 않았어요. 다시 시도하세요. 멈춘 곳부터 이어서 진행돼요.",
  "Your account couldn't be deleted. Try again in a moment.": "계정을 삭제할 수 없었어요. 잠시 후 다시 시도하세요.",
