  "The last staff account can't be deleted. Make another account staff first.": "마지막 스태프 계정은 삭제할 수 없어요. 먼저 다른 계정을 스태프로 지정하세요.",
  "Your account is being deleted right now. Wait a moment: this page carries on by itself.": "계정을 삭제하는 중이에요. 잠시 기다리세요. 이 페이지가 알아서 이어서 진행해요.",
