  "Ads already in Meta stay there": "Meta에 있는 광고는 그대로 남아요",
  "Ads you sent to your own Meta ad account are not deleted, and once your account is gone they can't be paused from here. Pause the ones that are running first.": "내 Meta 광고 계정에 보낸 광고는 삭제되지 않고, 계정이 삭제되면 여기서 일시 중지할 수 없어요. 게재 중인 광고는 먼저 일시 중지하세요.",
  "Open Launch › Ads": "게재 › 광고 열기",
