  "A product photo with its background removed, in an app's App settings › Brand.": "배경을 제거한 제품 사진으로, 앱의 앱 설정 › 브랜드에 있어요.",
  "No product images yet. Add photos or app screens in App settings › Brand, or the model will have to imagine your product.": "제품 이미지가 아직 없어요. 앱 설정 › 브랜드에서 사진이나 앱 화면을 추가해 주세요. 없으면 모델이 제품을 상상해서 그려야 해요.",
  "No product images yet. Add photos or app screens in App settings › Brand.": "제품 이미지가 아직 없어요. 앱 설정 › 브랜드에서 사진이나 앱 화면을 추가해 주세요.",
  "No product images yet. Add them in App settings › Brand.": "제품 이미지가 아직 없어요. 앱 설정 › 브랜드에서 추가해 주세요.",
  "Add your app's name in App settings › Profile first.": "먼저 앱 설정 › 프로필에서 앱 이름을 입력해 주세요.",
