  "The Superwall key can't list projects. Give it the projects:read scope too (it needs data:read and projects:read, with access to all projects).": "이 Superwall 키로는 프로젝트 목록을 볼 수 없어요. projects:read 범위도 주세요(data:read와 projects:read, 모든 프로젝트 접근 권한이 필요해요).",
